def _build_request(
    self, method: str, params: Optional[Dict[str, Any]] = None
) -> Dict[str, Any]:
    """Build a JSON-RPC request payload."""
    request: Dict[str, Any] = {
        "jsonrpc": "2.0",
        "id": self._get_next_id(),
        "method": method,
    }
    if params is not None:
        request["params"] = params
    return request

def _build_notification(self, method: str) -> Dict[str, Any]:
    """Build a JSON-RPC notification payload."""
    return {
        "jsonrpc": "2.0",
        "method": method,
    }
